  `build` VARCHAR(20) DEFAULT NULL,
  `gta_hash` VARCHAR(66) DEFAULT NULL,
  `gta_jhash` VARCHAR(66) DEFAULT NULL,
  `unused` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  INDEX `idx_namespace_id` (`namespace_id`),
  INDEX `idx_name` (`name`),
  INDEX `idx_hash` (`hash`),
  UNIQUE KEY `unique_native` (`namespace_id`, `name`),
  FOREIGN KEY (`namespace_id`) REFERENCES `namespaces`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

